package ledger

// Refactoring log (see .docs/instructions.md):
//
//  1. Validate the currency and locale up front, so invalid values are
//     rejected even when there are no entries. This removes the recursive
//     FormatLedger call that existed only to trigger currency validation
//     for an empty ledger.
//  2. Replace the hand-rolled, weight-coded selection sort with
//     sort.SliceStable and an explicit less function comparing date,
//     then description, then change.
//  3. Remove the goroutine-per-entry channel fan-out; entries are now
//     formatted sequentially and accumulated in a strings.Builder.
//  4. Extract the per-column formatting (date, description, amount)
//     into small helpers and build each line with fmt.Sprintf.
//  5. Replace the repeated strings.Repeat header construction with
//     literal header strings.
//
// The observable behavior is unchanged; the existing test suite passes.

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Entry is a single ledger entry. Change is expressed in cents.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger renders the entries as a formatted ledger for the given
// currency (USD or EUR) and locale (en-US or nl-NL). The entries are
// sorted by date, then description, then change; the input slice is not
// modified.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if currency != "USD" && currency != "EUR" {
		return "", errors.New("invalid currency")
	}
	if locale != "en-US" && locale != "nl-NL" {
		return "", errors.New("invalid locale")
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.SliceStable(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	if locale == "nl-NL" {
		b.WriteString("Datum      | Omschrijving              | Verandering\n")
	} else {
		b.WriteString("Date       | Description               | Change\n")
	}
	for _, entry := range sorted {
		line, err := formatEntry(locale, currency, entry)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// formatEntry renders a single ledger line.
func formatEntry(locale, currency string, entry Entry) (string, error) {
	date, err := formatDate(locale, entry.Date)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%-10s | %-25s | %13s\n",
		date, formatDescription(entry.Description), formatAmount(locale, currency, entry.Change)), nil
}

// formatDate validates a "Y-m-d" date and renders it in the locale's
// conventional order.
func formatDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errors.New("invalid date")
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if locale == "nl-NL" {
		return day + "-" + month + "-" + year, nil
	}
	return month + "/" + day + "/" + year, nil
}

// formatDescription pads the description to 25 characters, or truncates
// overlong ones with an ellipsis.
func formatDescription(desc string) string {
	if len(desc) > 25 {
		return desc[:22] + "..."
	}
	return desc + strings.Repeat(" ", 25-len(desc))
}

// formatAmount renders an amount in cents in the locale's convention:
// en-US uses "$1,234.56" (with parentheses for negatives) and nl-NL uses
// "$ 1.234,56" (with a trailing "-" for negatives).
func formatAmount(locale, currency string, cents int) string {
	symbol := "$"
	if currency == "EUR" {
		symbol = "€"
	}
	negative := cents < 0
	if negative {
		cents = -cents
	}
	whole, frac := cents/100, cents%100
	amount := groupThousands(strconv.Itoa(whole), thousandsSeparator(locale)) +
		decimalSeparator(locale) + fmt.Sprintf("%02d", frac)
	if locale == "nl-NL" {
		if negative {
			return symbol + " " + amount + "-"
		}
		return symbol + " " + amount + " "
	}
	if negative {
		return "(" + symbol + amount + ")"
	}
	return symbol + amount + " "
}

func thousandsSeparator(locale string) string {
	if locale == "nl-NL" {
		return "."
	}
	return ","
}

func decimalSeparator(locale string) string {
	if locale == "nl-NL" {
		return ","
	}
	return "."
}

// groupThousands inserts the separator every three digits from the right.
func groupThousands(digits, sep string) string {
	var groups []string
	for len(digits) > 3 {
		groups = append(groups, digits[len(digits)-3:])
		digits = digits[:len(digits)-3]
	}
	groups = append(groups, digits)
	for i, j := 0, len(groups)-1; i < j; i, j = i+1, j-1 {
		groups[i], groups[j] = groups[j], groups[i]
	}
	return strings.Join(groups, sep)
}
